function slug(value: string, suffix: string): string {
  const result = value.toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-+/g, '-')
    .slice(0, 52)
    .replace(/-+$/, '');
  return `${result || 'assisted-assessment'}-${suffix}`;
}
