  if (depth > 3) return { text: value, unwrapped: false };
  const marker = /(?:^|\n)#\s*Source check text \(preserved for review\):/m.exec(value);
  if (!marker) return { text: value, unwrapped: false };
  const tail = value.slice((marker.index ?? 0) + marker[0].length).replace(/^\r?\n/, '');
  const lines: string[] = [];
  for (const line of tail.split('\n')) {
    if (!line.trim()) { lines.push(''); continue; }
    if (!/^#(?:\s|$)/.test(line)) break;
    lines.push(line.replace(/^#\s?/, ''));
  }
  const extracted = cleanText(lines.join('\n'));
  if (!extracted) return { text: value, unwrapped: false };
  const nested = unwrapAssistedDraft(extracted, depth + 1);
