  const firstLine = cleanText(checkText).split('\n').map(line => line.trim())
    .map(line => line.replace(/^#\s?/, '').trim())
    .find(line => line && !/^(?:Assisted Assessment draft|Generated by the offline heuristic|Confidence:|Assumption:|Review needed:|Source check text|assessment:)\b/i.test(line)) ?? '';
