    if (/(?:password history|password complexity|reversible password|passwords?.*(?:length|characters?)|minimum password age|maximum password age)/i.test(text)) return candidate('windows.passwordpolicy', ['Used the Windows benchmark context to map effective password-policy wording to windows.passwordpolicy.', 'Confirm the exact policy metric, scope, and comparison boundary.']);
    if (/(?:Kerberos|ticket lifetime|clock synchronization|computer clock)/i.test(text)) return candidate('windows.wmi.query', ['Used the Windows benchmark context to map Kerberos or system-time policy to a native Windows query.', 'Confirm the exact policy key and numeric/unit interpretation.']);
    if (/(?:BitLocker PIN|computer account password|machine account password|blank passwords?)/i.test(text)) return candidate('windows.registry', ['Used the Windows benchmark context to map machine/security policy wording to windows.registry.', 'Confirm the exact policy value and acceptable state.']);
    if (/ECC Curves?/i.test(text)) return candidate('variable.value', ['Used the Windows benchmark context to map ordered ECC-curve policy to a variable-backed value comparison.', 'Confirm the approved curve order and comparison semantics.']);
    if (/Anonymous SID\/Name translation/i.test(text)) return candidate('windows.passwordpolicy', ['Used the Windows benchmark context to map the effective anonymous SID/name policy to the native policy capability.', 'Confirm the exact policy setting and disabled-state predicate.']);
    if (/(?:Software certificate installation files?|certificate files?).*(?:removed|deleted|untrusted)/i.test(text)) return candidate('windows.file', ['Used the Windows benchmark context to map certificate-installation file absence to windows.file.', 'Confirm the exact file paths and absence predicate.']);
    if (/(?:UEFI firmware|UEFI mode|BIOS)/i.test(text)) return candidate('windows.cmdlet', ['Used the Windows benchmark context to map firmware-mode verification to a native commandlet query.', 'Confirm the exact firmware property and accepted mode.']);
    if (/(?:Event Viewer|event log).*(?:permissions?|protected|access)/i.test(text)) return candidate('windows.fileeffectiverights', ['Used the Windows benchmark context to map event-log access control to windows.fileeffectiverights.', 'Confirm the exact event-log path, trustee, and rights predicate.']);
    if (/(?:default permissions|permissions?).*(?:HKEY_LOCAL_MACHINE|registry hive)/i.test(text)) return candidate('independent.shellcommand', ['Used the Windows benchmark context to map broad registry permission verification to command evidence.', 'Confirm the exact keys, trustees, and rights.']);
    if (/(?:Active Directory data files|Organizational Unit|OU objects?).*(?:permissions?|access control)/i.test(text)) return candidate('independent.shellcommand', ['Used the Windows benchmark context to map directory-object/file access-control verification to command evidence.', 'Confirm the exact object paths, trustees, and rights.']);
    if (/(?:Credential Guard|virtualization[- ]based (?:security|protection)|Win32_DeviceGuard|VBS)/i.test(text)) return candidate('windows.cmdlet', ['Used the Windows benchmark context to map Device Guard/VBS state to a native commandlet query.', 'Confirm the exact Device Guard property and accepted state.']);
