    if (/(?:password complexity|reversible password|password.*expiration|password never expires|Account.*password)/i.test(text)) return candidate(/reversible|complexity/i.test(text) ? 'windows.passwordpolicy' : 'windows.wmi.query', ['Used the Windows benchmark context to map account/password policy wording to the native Windows policy or account query.', 'Confirm the effective policy scope and comparison predicate.']);
    if (/(?:guest account|administrator account).*\b(?:renamed|disabled)/i.test(text)) return candidate(windowsVersion === '2016' ? 'independent.shellcommand' : /renamed/i.test(text) ? 'windows.sid_sid' : 'windows.user_sid', ['Used the Windows benchmark context to map built-in account state to the native SID/account collector.', 'Confirm the built-in account identifier and expected name or state.']);
    if (/(?:PKI server certificate)/i.test(text)) return candidate('windows.cmdlet', ['Used the Windows benchmark context to map domain-controller certificate inspection to a native commandlet query.', 'Confirm the certificate template/store and validity predicate.']);
    if (/(?:cross-certificates?|Root CA certificates?|certificate.*(?:Trusted Root|Untrusted Certificate|Store))/i.test(text)) return candidate('windows.registry', ['Used the Windows benchmark context to map certificate-store presence to the native registry/certificate policy collector.', 'Confirm the certificate store, subject/issuer, and validity predicate.']);
    if (/(?:Secure Boot|alternate operating systems|time service|w32tm)/i.test(text)) return candidate('independent.shellcommand', ['Used the Windows benchmark context to map firmware, boot, or time-service verification to command evidence.', 'Confirm the exact command and state predicate.']);
    if (/(?:supported servicing|supported version|Enterprise Edition|Edition.*64-bit)/i.test(text)) return candidate('windows.registry', ['Used the Windows benchmark context to map supported-release and edition checks to the native policy collector.', 'Confirm the accepted servicing level, edition, and architecture.']);
    if (/(?:registry hive|Registry Path|HKEY_)/i.test(text) && /HKEY_CURRENT_USER/i.test(text)) return candidate('windows.ntuser', ['Used the Windows benchmark context to map per-user registry policy to windows.ntuser.', 'Confirm the exact hive, key, value, and predicate.']);
    if (/(?:registry hive|Registry Path|HKEY_)/i.test(text)) return candidate('windows.registry', ['Used the Windows benchmark context to map machine registry policy to windows.registry.', 'Confirm the exact hive, key, value, and predicate.']);
